-- Bloom: initial setup for a dedicated Supabase project. No private keys in HTML.
begin;
create table if not exists public.bloom_profiles(user_id uuid primary key references auth.users(id) on delete cascade,display_name text not null default '' check(length(display_name)<=80),theme text not null default 'light' check(theme in ('light','dark')),focus_minutes integer not null default 25 check(focus_minutes between 1 and 180),break_minutes integer not null default 5 check(break_minutes between 1 and 60),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.bloom_tasks(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null check(length(title) between 1 and 160),subject text not null default '' check(length(subject)<=80),due_date date not null check(due_date between '2000-01-01' and '2100-12-31'),priority text not null default 'Medium' check(priority in ('Low','Medium','High')),status text not null default 'todo' check(status in ('todo','done')),completed_date date,notes text not null default '' check(length(notes)<=1000),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((status='done' and completed_date is not null) or (status='todo' and completed_date is null)));
create table if not exists public.bloom_habits(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null check(length(name) between 1 and 120),schedule text not null default 'Daily' check(schedule in ('Daily','Weekdays')),start_date date not null default current_date check(start_date between '2000-01-01' and '2100-12-31'),notes text not null default '' check(length(notes)<=1000),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,user_id));
create table if not exists public.bloom_habit_logs(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,habit_id uuid not null,log_date date not null check(log_date between '2000-01-01' and '2100-12-31'),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(habit_id,user_id) references public.bloom_habits(id,user_id) on delete cascade,unique(user_id,habit_id,log_date));
create table if not exists public.bloom_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,subject text not null check(length(subject) between 1 and 120),kind text not null check(kind in ('Focus','Break')),target_minutes integer not null check(target_minutes between 1 and 180),started_at timestamptz not null default now(),ended_at timestamptz,duration_seconds integer not null default 0 check(duration_seconds between 0 and 86400),session_date date not null check(session_date between '2000-01-01' and '2100-12-31'),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((ended_at is null and duration_seconds=0) or (ended_at is not null and ended_at>=started_at)));
create table if not exists public.bloom_goals(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null check(length(name) between 1 and 120),target integer not null check(target between 1 and 1000000),progress integer not null default 0 check(progress between 0 and 1000000),unit text not null default 'steps' check(length(unit) between 1 and 40),target_date date not null check(target_date between '2000-01-01' and '2100-12-31'),notes text not null default '' check(length(notes)<=1000),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists bloom_tasks_due on public.bloom_tasks(user_id,status,due_date);
create index if not exists bloom_habit_logs_dates on public.bloom_habit_logs(user_id,log_date);
create index if not exists bloom_habits_owner on public.bloom_habits(user_id);
create index if not exists bloom_goals_owner on public.bloom_goals(user_id);
create index if not exists bloom_sessions_dates on public.bloom_sessions(user_id,session_date);
create unique index if not exists bloom_one_timer on public.bloom_sessions(user_id) where ended_at is null;
create or replace function public.bloom_touch() returns trigger language plpgsql set search_path='' as $$begin if old.user_id<>new.user_id then raise exception 'Ownership cannot change';end if;new.updated_at=now();new.created_at=old.created_at;return new;end;$$;
revoke all on function public.bloom_touch() from public,anon,authenticated;
do $$declare t text;op text;begin foreach t in array array['bloom_profiles','bloom_tasks','bloom_habits','bloom_habit_logs','bloom_sessions','bloom_goals'] loop
 execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon',t);execute format('grant select,insert,update,delete on public.%I to authenticated',t);
 foreach op in array array['select','insert','update','delete'] loop execute format('drop policy if exists %I on public.%I',t||'_'||op,t);
 if op='insert' then execute format('create policy %I on public.%I for insert to authenticated with check((select auth.uid())=user_id)',t||'_'||op,t);
 elsif op='update' then execute format('create policy %I on public.%I for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id)',t||'_'||op,t);
 else execute format('create policy %I on public.%I for %s to authenticated using((select auth.uid())=user_id)',t||'_'||op,t,op);end if;end loop;
 execute format('drop trigger if exists bloom_touch on public.%I',t);execute format('create trigger bloom_touch before update on public.%I for each row execute function public.bloom_touch()',t);end loop;end;$$;
create or replace function public.bloom_finish_session(session_id uuid) returns void language plpgsql security invoker set search_path='' as $$declare s public.bloom_sessions%rowtype;begin select * into s from public.bloom_sessions where id=session_id and user_id=auth.uid() for update;if not found or s.ended_at is not null then raise exception 'Session unavailable or already saved';end if;update public.bloom_sessions set ended_at=now(),duration_seconds=least(s.target_minutes*60,greatest(0,floor(extract(epoch from now()-s.started_at))::integer)) where id=s.id and user_id=auth.uid();end;$$;
revoke all on function public.bloom_finish_session(uuid) from public,anon;grant execute on function public.bloom_finish_session(uuid) to authenticated;
create or replace function public.bloom_delete_account() returns void language plpgsql security definer set search_path='' as $$declare caller uuid:=auth.uid();begin if caller is null then raise exception 'Sign in required';end if;delete from auth.users where id=caller;end;$$;
revoke all on function public.bloom_delete_account() from public,anon;grant execute on function public.bloom_delete_account() to authenticated;
commit;
